const summary = $('Retrieve Actual Telemetry & Scan Stats').item.json;
const models = $('Retrieve Model Latency & Accuracy Baselines').item.json;
const campaigns = $('Retrieve Emerging Campaign Clusters').all().map(item => item.json);

const reportMarkdown = `# 🛡️ TRUSTLENS AI — Daily Executive Intelligence Report
**Report Date:** ${summary.report_date}
**Generated:** ${summary.generated_at}

## 📊 24-Hour Threat Telemetry
- **Total Scans Analyzed:** ${summary.telemetry_24h.total_threat_scans}
- **High/Critical Threats Blocked:** ${summary.telemetry_24h.high_severity_threats}
- **Clean Communications:** ${summary.telemetry_24h.clean_scans}
- **System Threat Ratio:** ${(summary.telemetry_24h.threat_ratio * 100).toFixed(1)}%

## 👥 Community Intelligence Queue
- **Verified Scams Added:** ${summary.community_reports.verified_scams}
- **Pending Review Queue:** ${summary.community_reports.pending_review}

## 🤖 Production Model Health
- **Model 1 (Multilingual Text):** ${models.models?.model1_text?.status || 'HEALTHY'}
- **Model 2 (Phishing URLs):** ${models.models?.model2_url?.status || 'HEALTHY'}
- **Model 3 (Tactic Multi-Label):** ${models.models?.model3_tactics?.status || 'HEALTHY'}
- **Model 4 (Campaign Clustering):** ${models.models?.model4_campaigns?.status || 'HEALTHY'}
- **Average Latency:** ${summary.model_health.avg_latency_ms} ms

## 🚨 Active Coordinated Campaign Clusters
Total Clusters Tracked: ${summary.active_campaign_clusters}

*Legal Disclaimer: Campaign similarity clusters indicate statistical linguistic and technical overlap; they do not establish judicial organizational attribution.*`;

return [{
  json: {
    report_date: summary.report_date,
    generated_at: summary.generated_at,
    markdown_body: reportMarkdown,
    telemetry: summary.telemetry_24h,
    top_campaigns_count: campaigns.length
  }
}];
